import re

def parse_color(text):
    if not isinstance(text, str):
        raise ValueError
    # Check for valid format
    match = re.fullmatch(r'^#([a-fA-F0-9]{3}|[a-fA-F0-9]{6})$', text)
    if not match:
        raise ValueError
    hex_str = match.group(1)
    if len(hex_str) == 3:
        # Expand to 6 digits by repeating each character
        hex_str = ''.join([c * 2 for c in hex_str])
    # Convert each pair to integer
    try:
        r = int(hex_str[0:2], 16)
        g = int(hex_str[2:4], 16)
        b = int(hex_str[4:6], 16)
    except ValueError:
        raise ValueError
    return (r, g, b)

def format_color(rgb):
    if not isinstance(rgb, (list, tuple)):
        raise ValueError
    if len(rgb) != 3:
        raise ValueError
    for x in rgb:
        if type(x) is not int:
            raise ValueError
        if not (0 <= x <= 255):
            raise ValueError
    # Convert each component to two hex digits
    hex_parts = []
    for c in rgb:
        hex_str = f"{c:02x}"
        hex_parts.append(hex_str)
    # Check if all parts have equal digits
    short_form = all(p[0] == p[1] for p in [hex_parts[0], hex_parts[1], hex_parts[2]])
    if short_form:
        return '#' + ''.join(p[0] for p in hex_parts)
    else:
        return '#' + ''.join(hex_parts)
