To convert between `snake_case` and `camelCase`, we validate and transform the input strings using regex for validation and string manipulation for transformation. For `snake_to_camel`, we split on underscores, capitalize subsequent words, and join. For `camel_to_snake`, we insert underscores before uppercase letters and lowercase all characters.

```python
import re

def snake_to_camel(name):
    if not isinstance(name, str) or not name:
        raise ValueError("Invalid snake_case name")
    if not re.fullmatch(r'^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$', name):
        raise ValueError("Invalid snake_case name")
    parts = name.split('_')
    return parts[0] + ''.join(word.capitalize() for word in parts[1:])

def camel_to_snake(name):
    if not isinstance(name, str) or not name:
        raise ValueError("Invalid camelCase name")
    if not re.fullmatch(r'^[a-z][a-zA-Z0-9]*$', name):
        raise ValueError("Invalid camelCase name")
    result = [name[0].lower()]
    for char in name[1:]:
        if char.isupper():
            result.extend(['_', char.lower()])
        else:
            result.append(char)
    return ''.join(result)
