To solve the problem, we implement two functions that strictly follow the formatting rules for monetary values. `cents_to_text` converts an integer (cents) into a string with proper dollar formatting, including commas and two decimal places. `text_to_cents` validates and parses such strings back into the original integer, ensuring strict adherence to the formatting rules.

```python
def cents_to_text(cents):
    if not isinstance(cents, int) or isinstance(cents, bool):
        raise ValueError("Input must be an integer")
    if cents == 0:
        return "0.00"
    is_negative = cents < 0
    cents = abs(cents)
    dollars = cents // 100
    cents_part = cents % 100
    # Format dollars with commas
    def format_with_commas(n):
        s = str(n)
        groups = []
        while s:
            groups.append(s[-3:])
            s = s[:-3]
        return ','.join(reversed(groups)) if len(groups) > 1 else groups[0]
    dollars_str = format_with_commas(dollars)
    sign = "-" if is_negative else ""
    return f"{sign}{dollars_str}.{cents_part:02d}"

def text_to_cents(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    # Check for valid structure: optional '-', digits with commas, '.', and two digits
    import re
    match = re.fullmatch(r"-?(?:\d{1,3}(?:,\d{3})*|\d{1})(\.\d{2})?", text)
    if not match:
        raise ValueError("Invalid format")
    parts = text.split('.')
    if len(parts) == 1:
        raise ValueError("Missing decimal part")
    if len(parts[1]) != 2:
        raise ValueError("Invalid decimal part")
    # Process the dollars part
    dollars_str, cents_str = parts[0], parts[1]
    if dollars_str == "":
        dollars_str = "0"
    # Check for leading zeros
    if len(dollars_str) > 1 and dollars_str[0] == '0':
        raise ValueError("Invalid leading zero")
    # Check commas in dollars part
    if ',' in dollars_str:
        groups = dollars_str.split(',')
        if len(groups[0]) == 0 or len(groups[0]) > 3:
            raise ValueError("Invalid comma placement")
        for group in groups[1:]:
            if len(group) != 3:
                raise ValueError("Invalid comma placement")
        dollars_str = dollars_str.replace(',', '')
    # Handle special cases like "-0.00"
    if dollars_str == "0" and len(text) > 3 and text[1] == '0':
        raise ValueError("Invalid format")
    total = int(dollars_str) * 100 + int(cents_str)
    if text.startswith('-'):
        total = -total
    return total
