To solve the problem, we first validate the input string by ensuring it conforms to the CIDR notation format. We then convert the IP address to a 32-bit integer and apply the prefix mask to compute the network range. The first and last addresses are determined by zeroing and setting all host bits, respectively, and the size is calculated as $2^{(32 - n)}$.

```python
def cidr_range(text):
    if not isinstance(text, str):
        raise ValueError
    parts = text.split('/')
    if len(parts) != 2:
        raise ValueError
    ip_str, prefix_str = parts
    if ip_str.count('.') != 3:
        raise ValueError
    ip_parts = ip_str.split('.')
    if len(ip_parts) != 4:
        raise ValueError

    def is_valid_part(s, max_val):
        if not s.isdigit():
            return False
        if len(s) > 1 and s[0] == '0':
            return False
        num = int(s)
        return 0 <= num <= max_val

    for p in ip_parts:
        if not is_valid_part(p, 255):
            raise ValueError
    if not is_valid_part(prefix_str, 32):
        raise ValueError

    prefix = int(prefix_str)
    ip_int = 0
    for p in ip_parts:
        ip_int = ip_int * 256 + int(p)

    host_bits = 32 - prefix
    network_mask = ((1 << prefix) - 1) << host_bits
    first_int = ip_int & network_mask
    last_int = first_int | ((1 << host_bits) - 1)
    size = 1 << host_bits if host_bits > 0 else 1

    def int_to_ip(n):
        octets = []
        for _ in range(4):
            octets.append(str(n % 256))
            n = n // 256
        return '.'.join(reversed(octets))

    first_str = int_to_ip(first_int)
    last_str = int_to_ip(last_int)
    return (first_str, last_str, size)
```

