import re

def to_24h(text):
    if not isinstance(text, str):
        raise ValueError
    match = re.fullmatch(r'^([1-9]|1[0-2]):([0-5][0-9]) (AM|PM)$', text)
    if not match:
        raise ValueError
    h = int(match.group(1))
    m = int(match.group(2))
    period = match.group(3)
    if period == 'AM' and h == 12:
        h_24 = 0
    elif period == 'PM' and h != 12:
        h_24 = h + 12
    else:
        h_24 = h
    return f"{h_24:02d}:{m:02d}"

def to_12h(text):
    if not isinstance(text, str):
        raise ValueError
    match = re.fullmatch(r'^([0-1][0-9]|2[0-3]):([0-5][0-9])$', text)
    if not match:
        raise ValueError
    h_24 = int(match.group(1))
    m = int(match.group(2))
    if h_24 == 0:
        return f"12:{m:02d} AM"
    elif 1 <= h_24 < 12:
        return f"{h_24}:{m:02d} AM"
    elif h_24 == 12:
        return f"12:{m:02d} PM"
    else:
        return f"{h_24 - 12}:{m:02d} PM"
