def luhn_valid(number):
    if not isinstance(number, str) or not number.isdigit():
        raise ValueError
    if len(number) < 2:
        raise ValueError
    total = 0
    reversed_digits = number[::-1]
    for i, ch in enumerate(reversed_digits):
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str) or not partial.isdigit():
        raise ValueError
    if len(partial) < 1:
        raise ValueError
    # Compute the sum as if the check digit is 0, then find the correct check digit
    total = 0
    reversed_partial = partial[::-1]
    for i, ch in enumerate(reversed_partial):
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    # The check digit is (10 - (total % 10)) % 10
    check_digit = (10 - (total % 10)) % 10
    return partial + str(check_digit)
