```python
def persistence(n):
    if type(n) is not int or n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n < 10:
        return (0, 0)

    def sum_digits(x):
        return sum(int(d) for d in str(x))

    def product_digits(x):
        p = 1
        for d in str(x):
            p *= int(d)
        return p

    additive = 0
    current = n
    while current >= 10:
        current = sum_digits(current)
        additive += 1

    multiplicative = 0
    current = n
    while current >= 10:
        current = product_digits(current)
        multiplicative += 1

    return (additive, multiplicative)

def digital_root(n):
    if type(n) is not int or n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 0
    return n - 9 * ((n - 1) // 9)
