def is_happy(n):
    if type(n) is not int:
        raise ValueError("n must be an int >= 1")
    if n < 1:
        raise ValueError("n must be an int >= 1")
    while True:
        if n == 1:
            return True
        if n == 4:
            return False
        # Compute sum of squares of digits
        total = 0
        while n > 0:
            digit = n % 10
            total += digit * digit
            n = n // 10
        n = total

def happy_count(limit):
    if type(limit) is not int:
        raise ValueError("limit must be an int from 0 to 100000")
    if not (0 <= limit <= 100000):
        raise ValueError("limit must be an int from 0 to 100000")
    count = 0
    for num in range(1, limit + 1):
        if is_happy(num):
            count += 1
    return count
