def euler_trail(n, edges):
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(edges, (list, tuple)):
        raise ValueError("edges must be a list or tuple")
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError("each edge must be a 2-element list or tuple")
        u, v = e
        if not isinstance(u, int) or not isinstance(v, int):
            raise ValueError("edge elements must be integers")
        if u < 0 or u >= n or v < 0 or v >= n:
            raise ValueError("vertex out of range")

    if not edges:
        return []

    in_degree = [0] * n
    out_degree = [0] * n
    adj = [[] for _ in range(n)]
    for u, v in edges:
        out_degree[u] += 1
        in_degree[v] += 1
        adj[u].append(v)

    for u in range(n):
        adj[u].sort()

    start = -1
    end = -1
    for u in range(n):
        diff = out_degree[u] - in_degree[u]
        if diff == 1:
            if start != -1:
                return None
            start = u
        elif diff == 0:
            pass
        elif diff == -1:
            if end != -1:
                return None
            end = u
        else:
