To determine the kind of triangle formed by three points, the function first validates that each point is a tuple or list of two integers. It then checks for degeneracy by detecting duplicate points or collinearity using the cross product. If degenerate, it returns `"degenerate"`. Otherwise, it calculates the squared distances between the points to classify the triangle by its sides and angles. The side classification is `"isosceles"` if any two side lengths are equal and `"scalene"` otherwise. The angle classification is determined by comparing the largest squared side length to the sum of the other two.

```python
def triangle_kind(a, b, c):
    for point in [a, b, c]:
        if not (isinstance(point, (tuple, list)) and len(point) == 2):
            raise ValueError
        x, y = point
        if type(x) is not int or type(y) is not int:
            raise ValueError
    ax, ay = a
    bx, by = b
    cx, cy = c
    if (ax == bx and ay == by) or (bx == cx and by == cy) or (ax == cx and ay == cy):
        return "degenerate"
    cross = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
    if cross == 0:
        return "degenerate"
    def squared_dist(p, q):
        dx = p[0] - q[0]
        dy = p[1] - q[1]
        return dx * dx + dy * dy
    d1 = squared_dist(a, b)
    d2 = squared_dist(b, c)
    d3 = squared_dist(c, a)
    sides = sorted([d1, d2, d3])
    s1, s2, s3 = sides
    side_class = "isosceles" if s1 == s2 or s2 == s3 else "scalene"
    if s3 == s1 + s2:
        angle_class = "right"
    elif s3 > s1 + s2:
        angle_class = "obtuse"
    else:
        angle_class = "acute"
    return (side_class, angle_class)
