To determine the center(s) of a tree and its radius, we use a BFS-based approach. First, we validate the input to ensure the tree structure is correct. Then, we perform BFS from an arbitrary node to find the farthest node `u`. Another BFS from `u` finds the farthest node `v`, determining the tree's diameter `D`. Reconstructing the path from `u` to `v` allows us to locate the center(s): if `D` is even, the center is the middle node; if odd, the two middle nodes. The radius is calculated as `(D + 1) // 2`.

```python
from collections import deque

def tree_centers(n, edges):
    if not isinstance(n, int) or n < 1 or n > 100000:
        raise ValueError
    if n == 1:
        if edges != []:
            raise ValueError
        return ([0], 0)
    if not isinstance(edges, (list, tuple)) or len(edges) != n - 1:
        raise ValueError
    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            raise ValueError
        a, b = e
        if not isinstance(a, int) or not isinstance(b, int) or a < 0 or a >= n or b < 0 or b >= n:
            raise ValueError

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        dist = [-1] * n
        parent = [-1] * n
        q = deque([start])
        dist[start] = 0
        farthest = start
        max_dist = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    if dist[v] > max_dist:
                        max_dist = dist[v]
                        farthest = v
                    q.append(v)
        return farthest, max_dist, parent

    u, _, _ = bfs(0)
    v, D, parent = bfs(u)

    path = []
    current = v
    while current != -1:
        path.append(current)
        current = parent[current]
    path = path[::-1]

    if D % 2 == 0:
        mid = D // 2
        centers = [path[mid]]
    else:
        mid1 = D // 2
        mid2 = mid1 + 1
        centers = [path[mid1], path[mid2]]

    radius = (D + 1) // 2
    return (sorted(centers), radius)
