To solve this problem, we simulate a robot's movement on a grid based on a sequence of commands. The robot starts at the 'S' position, facing north, and processes each command in order. The key aspects include tracking the robot's current direction, checking for valid movements, and recording all visited cells. The solution involves parsing the commands, updating the robot's direction and position, and maintaining a set of visited cells for accurate counting.

```python
def robot_walk(grid, commands):
    for c in commands:
        if c not in {'L', 'R', 'F'}:
            raise ValueError("Invalid command")

    # Find the start position
    start_row, start_col = None, None
    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == 'S':
                start_row, start_col = r, c
                break
        if start_row is not None:
            break

    # Direction mapping: 0=N, 1=E, 2=S, 3=W
    directions = [( -1, 0), (0, 1), (1, 0), (0, -1)]
    current_dir = 0  # Start facing North
    current_row, current_col = start_row, start_col

    visited = {(current_row, current_col)}

    for cmd in commands:
        if cmd == 'L':
            current_dir = (current_dir - 1) % 4
        elif cmd == 'R':
            current_dir = (current_dir + 1) % 4
        elif cmd == 'F':
            dr, dc = directions[current_dir]
            new_row = current_row + dr
            new_col = current_col + dc
            # Check if new position is valid
            if (0 <= new_row < len(grid)) and (0 <= new_col < len(grid[0])):
                if grid[new_row][new_col] != '#':
                    current_row, current_col = new_row, new_col
            # Add the new position to visited if it's different
            visited.add((current_row, current_col))

    # Determine the final facing direction as a character
    facing_map = {0: 'N', 1: 'E', 2: 'S', 3: 'W'}
    final_facing = facing_map[current_dir]

    return (current_row, current_col, final_facing, len(visited))
