To solve the problem, we use dynamic programming (DP) to count the number of valid ways to climb the stairs while avoiding broken steps. We define a DP array `ways` where `ways[i]` represents the number of ways to reach step `i`. Starting with `ways[0] = 1` (the base case), we iterate through each step `i` from 1 to `n`. For each step, if it's broken, we set `ways[i] = 0`. Otherwise, we sum all valid previous steps `i - s` for each `s` in `steps` where `s <= i`. The result is taken modulo `1000000007` to ensure it fits within the required range.

The function includes thorough input validation to ensure `n`, `steps`, and `broken` meet the problem's constraints. This includes checking types, ranges, and uniqueness of step sizes.

```python
def stair_ways(n, steps, broken):
    MOD = 10**9 + 7

    # Validate n
    if type(n) is not int or n < 0 or n > 100000:
        raise ValueError("n must be an int from 0 to 100000")

    # Validate steps
    if not isinstance(steps, (list, tuple, set)):
        raise ValueError("steps must be a list, tuple or set")
    steps = list(steps)
    if len(steps) == 0:
        raise ValueError("steps must have 1 to 10 elements")
    unique_steps = set(steps)
    if len(unique_steps) != len(steps):
        raise ValueError("steps must have different ints")
    for s in steps:
        if type(s) is not int:
            raise ValueError("steps elements must be ints")
        if s < 1 or s > 100:
            raise ValueError("steps elements must be from 1 to 100")
    steps = list(unique_steps)

    # Validate broken
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError("broken must be a list, tuple or set")
    broken = list(broken)
    broken_set = set(broken)
    if n == 0:
        if len(broken_set) > 0:
            raise ValueError("broken must be empty when n == 0")
    else:
        for b in broken:
            if type(b) is not int:
                raise ValueError("broken elements must be ints")
            if not (1 <= b <= n - 1):
                raise ValueError("broken elements must be from 1 to n-1")
    broken = broken_set

    # Handle n == 0
    if n == 0:
        return 1

    # Initialize DP array
    max_stair = n
    ways = [0] * (max_stair + 1)
    ways[0] = 1

    for i in range(1, max_stair + 1):
        if i in broken:
            ways[i] = 0
        else:
            total = 0
            for s in steps:
                if s <= i:
                    total += ways[i - s]
                    if total >= MOD:
                        total -= MOD
            ways[i] = total % MOD

    return ways[n]
