    for i in range(1, max_stair + 1):
        if i in broken:
            ways[i] = 0
        else:
            total = 0
            for s in steps:
                if s <= i:
                    total += ways[i - s]
                    if total >= MOD:
                        total -= MOD
            ways[i] = total % MOD

    return ways[n]

