def cidr_range(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    if text.count('.') != 3 or text.count('/') != 1:
        raise ValueError("Invalid CIDR notation")

    ip_part, prefix_part = text.split('/')

    # Validate IP part
    octets = ip_part.split('.')
    if len(octets) != 4:
        raise ValueError("Invalid IP address format")
    for octet in octets:
        if not octet.isdigit():
            raise ValueError("Invalid octet: non-digit characters")
        if len(octet) > 1 and octet[0] == '0':
            raise ValueError("Invalid octet: leading zero")
        if int(octet) > 255:
            raise ValueError("Octet exceeds 255")

    # Validate prefix part
    if not prefix_part.isdigit():
        raise ValueError("Invalid prefix: non-digit characters")
    if len(prefix_part) > 1 and prefix_part[0] == '0':
        raise ValueError("Invalid prefix: leading zero")
    n = int(prefix_part)
    if n < 0 or n > 32:
        raise ValueError("Prefix out of range")

    # Convert IP to integer
    ip_int = int.from_bytes(bytes.fromhex(''.join(f"{int(octet):02x}" for octet in octets)), byteorder='big')

    # Compute mask
    if n == 0:
        mask = 0
    else:
        mask = (0xFFFFFFFF << (32 - n)) & 0xFFFFFFFF

    # Compute network and broadcast addresses
    network = ip_int & mask
    broadcast = network | (~mask & 0xFFFFFFFF)

    # Function to convert 32-bit integer to dotted string
    def int_to_dotted(addr):
        return '.'.join(f"{(addr >> (24 - i*8)) & 0xFF}" for i in range(4))

    first = int_to_dotted(network)
    last = int_to_dotted(broadcast)
    size = 2 ** (32 - n) if n != 32 else 1

    return (first, last, size)

