### Approach

1. **parse_query(text)**:
   - **Input Validation**: Check if the input is a string. If not, raise a `ValueError`.
   - **Empty String Handling**: If the input string is empty, return an empty list.
   - **Splitting**: Split the input string by '&' to get individual key-value pairs.
   - **Validation of Parts**: Each part must contain exactly one '='. If any part is empty or does not meet this criteria, raise a `ValueError`.
   - **Decoding**: Each key and value is decoded by handling '+', which stands for a space, and '%' followed by two hex digits, which represents an ASCII character. Ensure that the decoded characters are within the valid ASCII range (00 to 7F).

2. **build_query(pairs)**:
   - **Input Validation**: Check if the input is a list or tuple of tuples, and each tuple contains two strings. Ensure keys are non-empty and all characters are valid ASCII.
   - **Encoding**: Each key and value is encoded by converting spaces to '+', and other characters to their corresponding percent-encoded form if they are not in the allowed set (A-Z, a-z, 0-9, '-', '.', '_', '~').

### Solution Code

```python
def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if text == "":
        return []
    parts = text.split("&")
    allowed_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~+")
    result = []
    for part in parts:
        if not part:
            raise ValueError("Empty part in query string")
        if part.count("=") != 1:
            raise ValueError("Part must contain exactly one '='")
        key, value = part.split("=", 1)
        if not key:
            raise ValueError("Key cannot be empty")
        def url_decode(s):
            decoded = []
            i = 0
            n = len(s)
            while i < n:
                c = s[i]
                if c == '+':
                    decoded.append(' ')
                    i += 1
                elif c == '%':
                    if i + 2 >= n:
                        raise ValueError("Incomplete percent escape")
                    hex_part = s[i+1:i+3]
                    if not all(ch in '0123456789abcdefABCDEF' for ch in hex_part):
                        raise ValueError("Invalid hex in percent escape")
                    code = int(hex_part, 16)
                    if code > 0x7F:
                        raise ValueError("Character code exceeds 0x7F")
                    decoded.append(chr(code))
                    i += 3
                else:
                    if c in allowed_chars:
                        decoded.append(c)
                        i += 1
                    else:
                        raise ValueError(f"Invalid character '{c}' in encoded string")
            return ''.join(decoded)
        decoded_key = url_decode(key)
        decoded_value = url_decode(value)
        result.append((decoded_key, decoded_value))
    return result

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("Pairs must be a list or tuple")
    allowed_chars = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
    result = []
    for pair in pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("Each pair must be a tuple of two strings")
        key, value = pair
        if not isinstance(key, str) or not key:
            raise ValueError("Key must be a non-empty string")
        if not isinstance(value, str):
            raise ValueError("Value must be a string")
        for c in key:
            if c not in allowed_chars and c != '+':
                if c == ' ':
                    pass
                else:
                    raise ValueError(f"Invalid character '{c}' in key")
        for c in value:
            if c not in allowed_chars and c != '+':
                if c == ' ':
                    pass
                else:
                    raise ValueError(f"Invalid character '{c}' in value")
        def url_encode(s):
            encoded = []
            for c in s:
                if c in allowed_chars:
                    encoded.append(c)
                elif c == ' ':
                    encoded.append('+')
                else:
                    encoded.append('%{:02X}'.format(ord(c)))
            return ''.join(encoded)
        encoded_key = url_encode(key)
