            if a[i] == b[j]:
                L[i][j] = L[i + 1][j + 1] + 1
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])

    # DP table for lex smallest LCS
    # dp[i][j] stores the lex smallest LCS of a[i:] and b[j:]
    dp = [[""] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                dp[i][j] = a[i] + dp[i + 1][j + 1]
            else:
                if L[i + 1][j] > L[i][j + 1]:
                    dp[i][j] = dp[i + 1][j]
                elif L[i + 1][j] < L[i][j + 1]:
                    dp[i][j] = dp[i][j + 1]
                else:
                    # When lengths are equal, choose the lex smaller one
                    dp[i][j] = min(dp[i + 1][j], dp[i][j + 1])

